function allPermissionKeys(){return PERMISSION_CATALOG.flatMap(g=>g.items.map(x=>x[0]))}
function permissionPresetForRoleName(name=''){
 const n=String(name).toLowerCase();
 const all=allPermissionKeys();
 if(n.includes('service manager')||n.includes('manager')||n.includes('supervisor'))return [...all];
 if(n.includes('admin')||n.includes('coordinator'))return ['dashboard.view','team.view','case.view','case.create','case.edit','case.assign','customer.view','customer.edit','machine.view','machine.edit','qc.view','qc.edit','qc.approve','calendar.view','calendar.edit','field.view','warranty.view','warranty.edit','documents.view','documents.edit','reports.view','reports.export','notifications.view','notifications.manage','line.view','line.manage'];
 if(n.includes('technician')||n==='r&d'||n.includes('engineer'))return ['dashboard.view','team.view','case.view','customer.view','machine.view','qc.view','qc.edit','calendar.view','field.view','field.status','field.checkin','field.report','field.media','field.signature','warranty.view','documents.view','reports.view','reports.export','notifications.view'];
 if(n.includes('sales')||n.includes('marketing'))return ['dashboard.view','case.view','case.create','customer.view','customer.edit','machine.view','qc.view','quotation.view','quotation.create','warranty.view','reports.view','reports.export','notifications.view'];
 return ['dashboard.view'];
}
function migrateLegacyPermissions(text='',roleName=''){
 if(Array.isArray(text))return [...new Set(text.filter(x=>allPermissionKeys().includes(x)))];
 const s=String(text||'').toLowerCase();
 if(!s)return permissionPresetForRoleName(roleName);
 if(s.includes('ทุกโมดูล')||s.includes('approval'))return permissionPresetForRoleName('Service Manager');
 const keys=new Set();
 if(s.includes('เคส'))['case.view','case.create','case.edit'].forEach(x=>keys.add(x));
 if(s.includes('ลูกค้า'))['customer.view','customer.edit'].forEach(x=>keys.add(x));
 if(s.includes('นัดหมาย'))['calendar.view','calendar.edit'].forEach(x=>keys.add(x));
 if(s.includes('เอกสาร'))['documents.view','documents.edit'].forEach(x=>keys.add(x));
 if(s.includes('รายงาน'))['reports.view','reports.export'].forEach(x=>keys.add(x));
 if(s.includes('หลักฐาน'))['field.view','field.media','field.report'].forEach(x=>keys.add(x));
 if(s.includes('ใบเสนอราคา'))['quotation.view','quotation.create'].forEach(x=>keys.add(x));
 if(s.includes('อนุมัติ'))keys.add('quotation.approve');
 return keys.size?[...keys]:permissionPresetForRoleName(roleName)
}
function normalizeRoleSetting(r={}){return{name:r.name||'Role',users:Number(r.users)||0,teamScope:r.teamScope||'',positionScope:r.positionScope||'',permissions:migrateLegacyPermissions(r.permissions,r.name||'')}}
