function roleScopeLabel(value,type='team'){const th=settings?.language!=='en';if(!value)return th?'ทุก'+(type==='team'?'ทีม':'ตำแหน่ง'):'All '+(type==='team'?'Teams':'Positions');return value}
function roleSelectOptions(list,selected='',type='team'){return list.map(v=>`<option value="${esc(v)}" ${String(selected||'')===String(v)?'selected':''}>${esc(roleScopeLabel(v,type))}</option>`).join('')}
function getRoleScopedUsers(role){const roleObj=typeof role==='string'?(settings.roles.find(r=>r.name===role)||{name:role}):(role||{});const name=String(roleObj.name||'').trim();const team=String(roleObj.teamScope||'').trim();const pos=String(roleObj.positionScope||'').trim();const seen=new Map();[...demoUsers,currentUser].filter(Boolean).forEach(u=>{if(!u?.id)return;if(!seen.has(u.id))seen.set(u.id,u)});return [...seen.values()].filter(u=>{const raw=String(u?.role||'').trim();const mapped=resolvePermissionRoleName(u);const okName=!name||mapped===name||raw===name;const okTeam=!team||String(u?.team||'').trim()===team;const okPos=!pos||raw===pos||raw.toLowerCase()===pos.toLowerCase();return okName&&okTeam&&okPos})}

