const DEMO_DB_MARKER='imode_demo_customer_database_v532_test10_20260828';
(function importCustomerDatabaseDemo(){
 if(((window.IMODE_ENV&&window.IMODE_ENV.production)||window.IMODE_NO_DEMO))return;   /* production, or the emptied test site: never demo customers */
 if(localStorage.getItem(DEMO_DB_MARKER)==='1')return;
 const dc=window.IMODE_DEMO_CUSTOMERS||[],dm=window.IMODE_DEMO_MACHINES||[],dw=window.IMODE_DEMO_WARRANTIES||[];
 const cids=new Set(customers.map(x=>x.id));dc.forEach(x=>{if(!cids.has(x.id))customers.push({...x})});
 const byMachineId=new Map(machines.map(x=>[x.id,x]));
 dm.forEach(x=>{
   const old=byMachineId.get(x.id);
   if(!old){const added={...x,nameTh:x.nameTh||x.name||'',nameEn:x.nameEn||x.name||''};machines.push(added);byMachineId.set(x.id,added);return}
   // V5.29 migration: fill S/L and bilingual metadata on imported/legacy demo rows without overwriting a user's manual S/L choice.
   if(old.size!=='S'&&old.size!=='L')old.size=x.size||'';
   if(!old.sizeStatus)old.sizeStatus=x.sizeStatus||'';
   if(!old.sizeBasis)old.sizeBasis=x.sizeBasis||'';
   if(!old.serviceSize)old.serviceSize=x.serviceSize||'';
   if(!old.nameTh)old.nameTh=x.nameTh||x.name||'';
   if(!old.nameEn)old.nameEn=x.nameEn||x.name||'';
 });
 const wids=new Set(warranties.map(x=>x.id));dw.forEach(x=>{if(!wids.has(x.id))warranties.push({...x})});
 localStorage.setItem(K.customers,JSON.stringify(customers));localStorage.setItem(K.machines,JSON.stringify(machines));localStorage.setItem(K.warranties,JSON.stringify(warranties));localStorage.setItem(DEMO_DB_MARKER,'1');
})();



