function fontUserKey(){return currentUser?.id||'guest'}
function clampFontScale(v){const min=Number(settings?.typographyConfig?.minScale||90),max=Number(settings?.typographyConfig?.maxScale||130);return Math.min(max,Math.max(min,Math.round(Number(v)||100)))}
function currentFontScale(){const saved=fontPreferences[fontUserKey()];return clampFontScale(saved??settings?.typographyConfig?.defaultScale??100)}
function saveFontPreference(v){const pct=clampFontScale(v);fontPreferences[fontUserKey()]=pct;localStorage.setItem(K.fontPrefs,JSON.stringify(fontPreferences));return pct}
function fontScaleLabel(v=currentFontScale()){const pct=clampFontScale(v);if(settings?.language==='en'){if(pct<=90)return'Small';if(pct<=100)return'Standard';if(pct<=110)return'Large';if(pct<=120)return'Extra Large';return'Maximum'}if(pct<=90)return'เล็ก';if(pct<=100)return'มาตรฐาน';if(pct<=110)return'ใหญ่';if(pct<=120)return'ใหญ่มาก';return'ใหญ่ที่สุด'}
function applyFontScale(){const pct=currentFontScale();document.documentElement.style.setProperty('--ui-font-scale',(pct/100).toFixed(2));document.documentElement.dataset.fontScale=String(pct);if(typeof fontQuickBtn!=='undefined'){fontQuickBtn.innerHTML=`<span class="font-aa">Aa</span><b>${pct}%</b>`;fontQuickBtn.title=settings?.language==='en'?`Font size ${pct}%`:`ขนาดตัวอักษร ${pct}%`}}
function setFontScaleLive(v){const pct=saveFontPreference(v);applyFontScale();if(typeof fontScaleRange!=='undefined')fontScaleRange.value=pct;if(typeof fontScaleValue!=='undefined')fontScaleValue.textContent=pct+'%';if(typeof fontScaleName!=='undefined')fontScaleName.textContent=fontScaleLabel(pct);if(typeof fontPreviewBox!=='undefined')fontPreviewBox.setAttribute('data-preview-scale',pct);if(typeof setTypographySummary!=='undefined')setTypographySummary.textContent=(settings.language==='en'?`${pct}% · ${fontScaleLabel(pct)}`:`${pct}% · ${fontScaleLabel(pct)}`)}window.setFontScaleLive=setFontScaleLive;
function adjustFontScale(delta){setFontScaleLive(currentFontScale()+Number(delta||0))}window.adjustFontScale=adjustFontScale;
function setFontPreset(v){setFontScaleLive(v)}window.setFontPreset=setFontPreset;
function resetFontScale(){setFontScaleLive(settings.typographyConfig?.defaultScale||100)}window.resetFontScale=resetFontScale;
