function resolvePermissionRoleName(user=currentUser){
 const raw=String(user?.permissionRole||user?.role||'');
 if(settings.roles.some(r=>r.name===raw))return raw;
 const n=raw.toLowerCase();
 if(n.includes('service manager'))return settings.roles.find(r=>r.name==='Service Manager')?.name||raw;
 if(n.includes('supervisor'))return settings.roles.find(r=>r.name==='Service Manager')?.name||raw;
 if(n.includes('executive secretary')||n.includes('admin')||n.includes('coordinator'))return settings.roles.find(r=>r.name==='Admin / Coordinator')?.name||raw;
 if(n.includes('technician')||n==='r&d'||n.includes('engineer'))return settings.roles.find(r=>r.name==='Technician')?.name||raw;
 if(n.includes('sales')||n.includes('marketing'))return settings.roles.find(r=>r.name==='Sales')?.name||raw;
 return raw
}
function roleUserCount(role){return getRoleScopedUsers(role).length}
function currentRoleConfig(){const n=resolvePermissionRoleName(currentUser);return settings.roles.find(r=>r.name===n)}
function canPermission(key){
 if(!settings.systemBehavior?.enforceRolePermissions)return true;
 if(!currentUser)return true; // prototype safety: do not lock the UI before Auth is connected
 const r=currentRoleConfig();if(!r)return false;return (r.permissions||[]).includes(key)
}
function requirePermission(key){if(canPermission(key))return true;toastMsg(settings.language==='en'?'You do not have permission for this action':'คุณไม่มีสิทธิ์ใช้งานฟังก์ชันนี้');return false}
