const esc=(v='')=>String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
/* 2026-09-25 - esc IS EXPORTED, and this one line is not cosmetic.
   `const esc` is a LEXICAL GLOBAL, so window.esc has always been undefined - the trap this
   project has recorded since part 17 section 5 for currentUser/settings/cases, and again in
   part 30 for fmt and fmtDay. 48 patch files each carry
       function esc2(v){return typeof window.esc==='function'?window.esc(v):String(v==null?'':v)}
   whose fallback does NOT escape. So all 925 esc2() calls in this project were pass-throughs,
   and every one of them that writes into innerHTML rendered stored text as live markup.
   Measured before this line existed: an <img src=x onerror=...> stored in a machine name ran
   on the assign page and in the notification centre, on every page, because renderAll()
   renders every module. Anyone who can write a customer or machine name can do that, and
   04-anon-uat.sql currently lets anyone on the internet write one.
   Exporting the real function repairs all 48 files at once. fmt and fmtDay are still
   lexical-only; export them the same way if a patch file ever needs them. */
window.esc=esc;
/* 2026-10-09 security: esc() is the wrong encoder for a value inside a JS string in an inline
   handler (onclick="fn('...')"). The HTML parser decodes &quot; / &#39; back into quotes BEFORE
   the handler is compiled, so an id containing a quote closes the string and runs as script.
   imodeJsArg returns a complete single-quoted JS string literal in which every character that
   could end the string or the attribute (\ ' " < > & and line breaks) is written as \uXXXX:
   write fn(${imodeJsArg(id)}), never fn('${id}') or fn(&quot;'+esc2(id)+'&quot;). An ordinary
   id comes out exactly as before - fn('C-123') - so the patches that read the onclick text back
   with /\('([^']+)'\)/ (js/27, 60, 64, 99, 102, 106, 119...) keep working. Ids reach these
   handlers from the portal (portal_submit lets an anonymous customer choose them) and from any
   staff role. */
function imodeJsArg(v){var s=String(v==null?'':v),o='';for(var k=0;k<s.length;k++){var c=s.charCodeAt(k);o+=(c<32||c===34||c===38||c===39||c===60||c===62||c===92||c===8232||c===8233)?'\\u'+('000'+c.toString(16)).slice(-4):s[k]}return "'"+o+"'"}
window.imodeJsArg=imodeJsArg;
/* 2026-10-09 security: stored links (customer mapUrl, document/warranty URL, LINE add-friend URL)
   are typed by staff and synced to everyone, so a "javascript:" link would run in whoever clicks
   it. Only open http(s) / line / tel / mailto, plus data: files when allowData is set (uploaded
   attachments) - never data: HTML/SVG/XML/script. Returns the link unchanged, or '' to refuse. */
function imodeSafeUrl(u,allowData){const s=String(u==null?'':u).trim();if(!s)return'';if(/^data:/i.test(s))return allowData&&!/^data:\s*(text\/html|text\/xml|text\/javascript|image\/svg|application\/(xhtml|xml|javascript|ecmascript))/i.test(s)?s:'';try{const p=new URL(s,location.href);return /^(https?|line|tel|mailto):$/.test(p.protocol)?s:''}catch(e){return''}}
window.imodeSafeUrl=imodeSafeUrl;
