function genTicket(){const d=new Date(),p=`SRV-${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}-`;let n=1;cases.forEach(c=>{if(c.ticket?.startsWith(p))n=Math.max(n,(parseInt(c.ticket.split('-').pop())||0)+1)});return p+String(n).padStart(3,'0')}
