/* 2026-09-16: a job can belong to several technicians (js/38 keeps the crew in `assignees`
   and folds it into the one `assignee` column as a comma list, because service_cases has no
   column for it). Every place that ASKS "is this technician on this job" therefore has to go
   through the crew, or a technician who is not the lead is invisible: their queue shows 0 and
   nobody tells them they were given the work. Display of a single name is a different
   question and still uses techById(c.assignee) — the lead is who is responsible.
   The fallback keeps this working if js/38 is ever removed. */
function caseHasTech(c,tid){
 if(!tid||!c)return false;
 return (typeof window.imodeIsAssignedTo==='function')?window.imodeIsAssignedTo(c,tid):c.assignee===tid;
}window.caseHasTech=caseHasTech;
