 caseCards.innerHTML=list.length?list.map(c=>`<div class="mobile-data-card case-clickable" data-case-id="${esc(c.id)}" tabindex="0" aria-label="${esc(c.ticket)}" onclick="openCaseFromRow(event)" onkeydown="openCaseFromRow(event)"><div class="card-top"><div><h4>${esc(c.ticket)}</h4><p>${esc(c.customer)} · ${esc(c.machine)}</p></div>${badge('prio',c.priority)}</div><p>${esc(c.issue).slice(0,90)}</p><div class="card-meta">${badge('status',c.status)}<span class="badge">${esc(techById(c.assignee)?.name||'ยังไม่มอบหมาย')}</span></div><div class="card-actions"><button class="soft-btn" onclick="openCaseDetail(${imodeJsArg(c.id)})">ดูรายละเอียด</button><button class="primary-btn" onclick="openCaseModal(${imodeJsArg(c.id)})">แก้ไข</button>${caseQuotationButton(c,'soft-btn')}</div></div>`).join(''):'<div class="empty">ไม่พบข้อมูล</div>';
