/* 2026-09-15: the team vocabulary. It was two values; แอดมิน / เซลส์ / ผู้จัดการ were added so
   that everyone with a login has a group on the ทีมงาน page, not only technicians. `Admin` and
   `Management` are the spellings the seeded people at js/03:206-207 already carry — nothing was
   renamed. An unknown team falls back to Technical, which is what every caller did before. */
const TEAM_META={
 'Technical':{cls:'technical',icon:'🛠',th:'ทีม Technical',en:'Technical'},
 'R&D':{cls:'rd',icon:'🧪',th:'ทีม R&D',en:'R&D'},
 'Admin':{cls:'adminteam',icon:'🗂',th:'แอดมิน',en:'Admin'},
 'Sales':{cls:'sales',icon:'💼',th:'เซลส์',en:'Sales'},
 'Management':{cls:'management',icon:'👔',th:'ผู้จัดการ',en:'Management'},
 /* 2026-09-25: asked for — "ทีม Dev". */
 'Dev':{cls:'devteam',icon:'💻',th:'ทีม Dev',en:'Dev'}
};
const TEAM_LIST=Object.keys(TEAM_META);
function teamMeta(team){return TEAM_META[team]||TEAM_META['Technical']}
function teamLabel(team){const m=teamMeta(team);return settings.language==='en'?m.en:m.th}
function teamClass(team){return teamMeta(team).cls}
function teamBadge(team){const t=team||'Technical',m=teamMeta(t);return `<span class="team-badge ${m.cls}">${m.icon} ${esc(settings.language==='en'?m.en:m.th)}</span>`}
const MACHINE_FAMILY_PHOTOS=Object.freeze({
 hydrogenHo500:'./assets/machines/hydrogen-ho500wt.webp',
 hydrogenHo200:'./assets/machines/hydrogen-ho200wt.webp',
 nitrogen:'./assets/machines/nitrogen-generator.webp',
 laserMarking:'./assets/machines/laser-marking-bgf20.jpg',
 laserWelding:'./assets/machines/laser-welding.webp',
 blueThunder:'./assets/machines/welding-blue-thunder.jpg',
 centrifugalVa20:'./assets/machines/centrifugal-va20.jpg',
 centrifugalVa38:'./assets/machines/centrifugal-va38.jpg',
 polishingFamily:'./assets/machines/polishing-family.webp'
});
function machineFamilyPhoto(m){
 const text=[m?.model,m?.name,m?.nameTh,m?.nameEn].filter(Boolean).join(' ').toLowerCase();
 const compact=text.replace(/[\s_-]+/g,'');
 if(compact.includes('ho500wt'))return MACHINE_FAMILY_PHOTOS.hydrogenHo500;
 if(compact.includes('ho200wt'))return MACHINE_FAMILY_PHOTOS.hydrogenHo200;
 if(/\bn\s*-?\s*(20|40)\b/i.test(text)||text.includes('nitrogen gas generator')||text.includes('เครื่องผลิตแก๊สไนโตรเจน'))return MACHINE_FAMILY_PHOTOS.nitrogen;
 if(/blue\s*-?\s*thunder/i.test(text))return MACHINE_FAMILY_PHOTOS.blueThunder;
 if(/laser\s*weld|bull\s*thunder|เครื่องเชื่อมเลเซอร์/i.test(text))return MACHINE_FAMILY_PHOTOS.laserWelding;
 if(/bgf\s*-?\s*20|laser\s*mark|เครื่องมาร์กเลเซอร์/i.test(text))return MACHINE_FAMILY_PHOTOS.laserMarking;
 if(/\bva\s*38\b/i.test(text))return MACHINE_FAMILY_PHOTOS.centrifugalVa38;
 if(/\bva\s*20\b/i.test(text))return MACHINE_FAMILY_PHOTOS.centrifugalVa20;
 if(/\bva\s*18\b|20\s*l\s*x\s*3|\bmsh\b|gyratory\s*polish|เครื่องขัดระบบไจเรต/i.test(text))return MACHINE_FAMILY_PHOTOS.polishingFamily;
 if(/centrifugal\s*disc\s*finishing|เครื่องขัดแบบจานหมุนเหวี่ยง/i.test(text))return MACHINE_FAMILY_PHOTOS.polishingFamily;
 return '';
}
window.machineFamilyPhoto=machineFamilyPhoto;
function machineMediaHTML(m,large=false){
 const actualPhoto=String(m?.photo||'').trim();
 const familyPhoto=actualPhoto?'':machineFamilyPhoto(m);
 const src=actualPhoto||familyPhoto;
 const frameClass=large?'machine-thumb-lg':'machine-thumb';
 if(!src)return `<div class="${frameClass} machine-thumb-placeholder">No Image</div>`;
 const label=familyPhoto?`<span class="machine-reference-badge">${typeof settings!=='undefined'&&settings.language==='en'?'Reference Image':'ภาพอ้างอิง'}</span>`:'';
 const onerror="const p=this.parentElement;this.onerror=null;if(p){p.textContent='No Image';p.classList.add('machine-thumb-placeholder');p.classList.remove('has-family-photo')}";
 return `<div class="${frameClass}${familyPhoto?' has-family-photo':''}"><img src="${esc(src)}" alt="${esc(machinePrimaryName(m)||'Machine')}" loading="lazy" onerror="${onerror}">${label}</div>`;
}
