let pendingWarrantyAttachment=null,pendingMachineDocumentFile=null,warrantyPresetMachine='',documentPresetMachine='';
function dateISO(v){return v?new Date(v+'T00:00:00'):null}
/* 2026-09-19 — LOCAL calendar date, never UTC.
   `todayISO()` is the date in UTC and Thailand is UTC+7, so
   between 00:00 and 06:59 local it answers YESTERDAY. Every "today" in this project used
   it: the dashboard's นัดหมายวันนี้ key (compared against c.appointment, which IS local),
   and the default date on the QC / petty cash / purchase order / machine document /
   quotation / warranty forms.
   addMonthsISO() had the same fault one step worse: dateISO() builds a LOCAL midnight and
   toISOString() reads it back in UTC, so the warranty end date came out one day early
   ALWAYS, not only before 07:00 — measured, 2026-09-19 + 12 months gave 2027-09-18.
   localISO() serialises the date parts the user actually sees. Use it for a date-only
   string; createdAt / updatedAt stay full UTC ISO timestamps and are untouched. */
function localISO(v){const x=(v instanceof Date)?v:new Date(v);if(isNaN(x.getTime()))return '';return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0')}
function todayISO(){return localISO(new Date())}
window.localISO=localISO;window.todayISO=todayISO;
function addMonthsISO(dateStr,months){if(!dateStr)return'';const d=dateISO(dateStr);const original=d.getDate();d.setMonth(d.getMonth()+Number(months||0));if(d.getDate()<original)d.setDate(0);return localISO(d)}
function warrantyNo(){const d=new Date(),p=`WTY-${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}-`;let n=1;warranties.forEach(w=>{if(w.warrantyNo?.startsWith(p))n=Math.max(n,(parseInt(w.warrantyNo.split('-').pop())||0)+1)});return p+String(n).padStart(3,'0')}
function warrantyState(w){const now=new Date();now.setHours(0,0,0,0);const s=dateISO(w.startDate),e=dateISO(w.endDate);if(!e)return'none';if(s&&now<s)return'upcoming';if(now>e)return'expired';const days=Math.ceil((e-now)/86400000);return days<=Number(settings.warrantyConfig?.reminderDays||30)?'expiring':'active'}
function warrantyStateLabel(s){return ({active:'อยู่ในประกัน',expiring:'ใกล้หมดอายุ',expired:'หมดประกัน',upcoming:'ยังไม่เริ่ม',none:'ไม่ระบุ'}[s]||s)}
function warrantyDaysLeft(w){const e=dateISO(w.endDate);if(!e)return null;const now=new Date();now.setHours(0,0,0,0);return Math.ceil((e-now)/86400000)}
function latestWarrantyForMachine(mid){return [...warranties].filter(w=>w.machineId===mid).sort((a,b)=>new Date(b.endDate||0)-new Date(a.endDate||0))[0]}
function setWarrantyStatusFilter(v){warrantyStatusFilter.value=v;renderWarranties()}window.setWarrantyStatusFilter=setWarrantyStatusFilter;
function renderWarranties(){
 if(typeof warrantyTable==='undefined')return;
 const q=(warrantySearch.value||'').toLowerCase(),sf=warrantyStatusFilter.value||'all',mf=warrantyMachineFilter.value||'';
 const mv=warrantyMachineFilter.value;warrantyMachineFilter.innerHTML='<option value="">ทุกเครื่อง</option>'+machines.map(m=>`<option value="${esc(String(m.id))}">${esc(machineOptionLabel(m))}</option>`).join('');if(machines.some(m=>m.id===mv))warrantyMachineFilter.value=mv;
 const stats={active:0,expiring:0,expired:0,upcoming:0};warranties.forEach(w=>stats[warrantyState(w)]++);wActive.textContent=stats.active;wExpiring.textContent=stats.expiring;wExpired.textContent=stats.expired;wTotal.textContent=warranties.length;
 const filtered=warranties.filter(w=>{const m=machineById(w.machineId),cu=customerById(w.customerId),state=warrantyState(w);return (!q||[w.warrantyNo,cu?.name,m?.name,m?.model,m?.serial].join(' ').toLowerCase().includes(q))&&(sf==='all'||state===sf)&&(!mf||w.machineId===mf)}).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
 const info=paginateList('warranty',filtered,[q,sf,mf].join('|')),list=info.list;
 warrantyTable.innerHTML=list.length?list.map(w=>{const m=machineById(w.machineId),cu=customerById(w.customerId),state=warrantyState(w),days=warrantyDaysLeft(w),caseCount=cases.filter(c=>c.machineId===w.machineId&&c.createdAt&&dateISO(String(c.createdAt).slice(0,10))>=dateISO(w.startDate)&&dateISO(String(c.createdAt).slice(0,10))<=dateISO(w.endDate)).length;return `<tr><td><b class="ticket">${esc(w.warrantyNo)}</b></td><td>${esc(cu?.name||'-')}</td><td><div class="warranty-machine">${machineMediaHTML(m)}<div><b>${esc(m?.name||'-')}</b><small>${esc(m?.model||'-')} · S/N ${esc(m?.serial||'-')}</small></div></div></td><td>${fmtDay(w.startDate)}</td><td>${fmtDay(w.endDate)}${days!==null?`<span class="warranty-days">${days>=0?`เหลือ ${days} วัน`:`เกิน ${Math.abs(days)} วัน`}</span>`:''}</td><td><span class="warranty-status ${state}">${warrantyStateLabel(state)}</span></td><td>${caseCount}</td><td><button class="mini-btn" onclick="previewWarrantyCertificate(${imodeJsArg(w.id)})">ใบรับประกัน</button>${w.attachmentData||w.attachmentUrl?` <button class="mini-btn" onclick="openWarrantyAttachment(${imodeJsArg(w.id)})">แนบ</button>`:''}</td><td><button class="mini-btn" onclick="openWarrantyDetail(${imodeJsArg(w.id)})">ดู</button> <button class="mini-btn" onclick="openWarrantyModal(${imodeJsArg(w.id)})">แก้ไข</button></td></tr>`}).join(''):`<tr><td colspan="9"><div class="empty">ยังไม่มี Warranty ตามเงื่อนไข</div></td></tr>`;
 warrantyCards.innerHTML=list.length?list.map(w=>{const m=machineById(w.machineId),cu=customerById(w.customerId),state=warrantyState(w);return `<div class="mobile-data-card"><div class="card-top"><div><h4>${esc(w.warrantyNo)}</h4><p>${esc(cu?.name||'-')} · ${esc(m?.name||'-')}</p></div><span class="warranty-status ${state}">${warrantyStateLabel(state)}</span></div><p>${esc(m?.model||'-')} · S/N ${esc(m?.serial||'-')}<br>${fmtDay(w.startDate)} → ${fmtDay(w.endDate)}</p><div class="card-actions"><button class="soft-btn" onclick="previewWarrantyCertificate(${imodeJsArg(w.id)})">ใบรับประกัน</button><button class="primary-btn" onclick="openWarrantyDetail(${imodeJsArg(w.id)})">รายละเอียด</button></div></div>`}).join(''):'<div class="empty">ยังไม่มี Warranty</div>';
 renderListPager('warranty',info,warranties.length);
}
