 const obj={id:old?.id||uid(),name:cuName.value.trim(),branch:cuBranch.value.trim(),contact:cuContact.value.trim(),phone:cuPhone.value.trim(),email:cuEmail.value.trim(),location:cuLocation.value.trim(),address:cuAddress.value.trim(),mapUrl:cuMapUrl.value.trim(),latitude:cuLat.value.trim(),longitude:cuLng.value.trim(),note:cuNote.value.trim(),lineUserId:old?.lineUserId||'',lineDisplayName:old?.lineDisplayName||'',lineLinkedAt:old?.lineLinkedAt||''};
 if(old)customers=customers.map(x=>x.id===obj.id?obj:x);else customers.push(obj);
