function renderMachineNamePagePreviews(){const box=document.getElementById('machineNamePagePreviews');if(!box)return;box.innerHTML=[['Factory Name page',pendingFactoryNamePagePhoto],['Imode name page',pendingImodeNamePagePhoto]].map(([label,src])=>'<span style="display:inline-flex;align-items:center;gap:6px;margin:4px 12px 0 0">'+(src?'<img src="'+src+'" alt="'+label+'" style="width:38px;height:32px;object-fit:contain;border-radius:5px">':'')+label+': '+(src?'มีรูปแล้ว':'ยังไม่มีรูป')+'</span>').join('')}
function previewMachineNamePagePhoto(input,kind){const file=input.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toastMsg('กรุณาเลือกไฟล์รูปภาพ');return}machineNamePageTask=machineNamePageTask.then(async()=>{let source=file;if(typeof window.imodeCropImage==='function'){const cropped=await window.imodeCropImage(file,{aspect:0,maxOut:900,title:kind==='factory'?'ครอบตัด Factory Name page':'ครอบตัด Imode name page'});if(!cropped)return;source=cropped.file}const p=machineFilePopup(source),url=URL.createObjectURL(source);if(p)p.setPct(96);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const scale=Math.min(1,900/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.78);if(kind==='factory')pendingFactoryNamePagePhoto=data;else pendingImodeNamePagePhoto=data;renderMachineNamePagePreviews();if(p)p.setPct(96);machineFileDone(p,false,'เพิ่มรูปแล้ว: '+(kind==='factory'?'Factory Name page':'Imode name page'))}catch(e){console.warn(e);machineFileDone(p,true,'เตรียมรูปไม่สำเร็จ')}finally{URL.revokeObjectURL(url)}}).catch(err=>{console.warn(err);toastMsg('อ่านรูปไม่สำเร็จ')});input.value=''}
window.previewMachineNamePagePhoto=previewMachineNamePagePhoto;
function openMachineDetail(mid){const m=machineById(mid);if(!m)return;const cu=customerById(m.customerId),cs=cases.filter(c=>c.machineId===m.id);openModal(machinePrimaryName(m),`${machineSecondaryName(m)} · ${m.model||'-'} · S/N ${m.serial||'-'}`,`<div class="machine-detail-layout"><div>${machineMediaHTML(m,true)}${[["Factory Name page",m.factoryNamePagePhoto],["Imode name page",m.imodeNamePagePhoto]].filter(x=>x[1]).map(x=>`<div style="margin-top:12px"><b style="display:block;margin-bottom:5px">${esc(x[0])}</b><button type="button" class="machine-name-photo-open" data-mid="${esc(m.id)}" data-photo="${esc(String(x[0]==='Factory Name page'?'factory':'imode'))}" aria-label="เปิดดูรูป ${esc(x[0])}" style="display:block;width:100%;padding:0;border:0;background:none;cursor:zoom-in"><img src="${esc(x[1])}" alt="${esc(x[0])}" style="width:100%;max-height:220px;object-fit:contain;border-radius:10px"></button></div>`).join('')}</div><div><div class="detail-grid"><div class="detail-box full bilingual-machine-detail"><small>ชื่อเครื่อง / Machine Name</small><b>${esc(machineNameTh(m))}</b><span>${esc(machineNameEn(m))}</span></div><div class="detail-box"><small>ลูกค้า</small><b>${esc(cu?.name||'-')}</b></div><div class="detail-box"><small>Model</small><b>${esc(m.model||'-')}</b></div><div class="detail-box"><small>Serial No.</small><b>${esc(m.serial||'-')}</b></div><div class="detail-box"><small>ปีออกเครื่อง</small><b>${esc(m.issueYear||'-')}</b></div><div class="detail-box"><small>สถานะ Service</small><b>${esc(m.serviceStatus||'-')}</b></div><div class="detail-box"><small>ขนาด Service</small><b>${esc(m.size||'รอ Confirm')} ${m.serviceSize?`· ${esc(m.serviceSize)}`:''}</b><span class="subtext">${esc(m.sizeStatus||'')}</span></div><div class="detail-box"><small>ประกัน</small><b>${esc(m.warranty||'-')}</b></div><div class="detail-box"><small>PM ถัดไป</small><b>${esc(m.pmDue||'-')}</b></div><div class="detail-box"><small>จำนวนเคส</small><b>${cs.length}</b></div><div class="detail-box full"><small>หมายเหตุ</small><b>${esc(m.note||'-')}</b></div></div><div class="section-title" style="margin-top:14px">ประวัติ Service</div><div class="related-list">${cs.length?cs.map(c=>`<div class="related-item" onclick="closeModal();openCaseDetail(${imodeJsArg(c.id)})" style="cursor:pointer"><b>${esc(c.ticket)} · ${esc(c.issue).slice(0,70)}</b><small>${esc(c.status)} · ${fmt(c.createdAt)}</small></div>`).join(''):'<div class="empty">ยังไม่มีประวัติ</div>'}</div><div class="button-row" style="margin-top:14px"><button class="soft-btn" onclick="closeModal();openWarrantyForMachine(${imodeJsArg(m.id)})">🛡 Warranty</button><button class="soft-btn" onclick="closeModal();openDocsForMachine(${imodeJsArg(m.id)})">📁 เอกสารเครื่อง</button><button class="soft-btn" onclick="closeModal();openCustomerDetail(${imodeJsArg(cu?.id||'')})">ดูลูกค้า</button><button class="primary-btn" onclick="openCaseForMachine(${imodeJsArg(m.id)})">＋ เปิดเคสเครื่องนี้</button></div></div></div>`)}window.openMachineDetail=openMachineDetail;
function openMachineNamePhoto(mid,kind){const m=machineById(mid);const src=m&&(kind==='factory'?m.factoryNamePagePhoto:m.imodeNamePagePhoto);if(!src)return;const old=document.getElementById('machineNamePhotoLightbox');if(old)old.remove();const wrap=document.createElement('div');wrap.id='machineNamePhotoLightbox';wrap.className='cm-lightbox';wrap.setAttribute('role','dialog');wrap.setAttribute('aria-modal','true');const inner=document.createElement('div');inner.className='cm-lightbox-inner';const img=document.createElement('img');img.src=src;img.alt=kind==='factory'?'Factory Name page':'Imode name page';const bar=document.createElement('div');bar.className='cm-lightbox-bar';const title=document.createElement('b');title.textContent=img.alt;const close=document.createElement('button');close.type='button';close.className='cm-lightbox-close';close.textContent='×';close.setAttribute('aria-label','ปิดรูป');bar.append(title,close);inner.append(img,bar);wrap.appendChild(inner);document.body.appendChild(wrap);function dismiss(){document.removeEventListener('keydown',key,true);wrap.remove()}function key(e){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();dismiss()}}close.addEventListener('click',dismiss);wrap.addEventListener('click',e=>{if(e.target===wrap)dismiss()});document.addEventListener('keydown',key,true);close.focus()}
document.getElementById('modalBody').addEventListener('click',function(e){const btn=e.target.closest('.machine-name-photo-open');if(btn)openMachineNamePhoto(btn.dataset.mid,btn.dataset.photo)});
