function travelRow(z={}){return `<div class="travel-row"><input data-k="name" placeholder="Zone" value="${esc(z.name||'')}"><input data-k="min" type="number" min="0" placeholder="Min km" value="${esc(String(z.min??0))}"><input data-k="max" type="number" min="0" placeholder="Max km" value="${esc(String(z.max??''))}"><input data-k="fee" type="number" min="0" placeholder="Fee" value="${esc(String(z.fee??0))}"><input data-k="perKm" type="number" min="0" placeholder="บาท/km" value="${esc(String(z.perKm??0))}"><button class="danger-btn" onclick="this.parentElement.remove()">ลบ</button></div>`}
function openTravelSettingModal(){openModal('Travel Zone','แก้ไขช่วงระยะทาง ค่าเดินทางแบบเหมาจ่าย หรือบาทต่อกิโลเมตร',`<div class="setting-help" style="margin-bottom:9px">ถ้าใส่ “บาท/km” มากกว่า 0 ระบบจะใช้ระยะทาง × บาท/km แทนค่าเหมาจ่ายของ Zone นั้น</div><div id="travelList">${settings.travelZones.map(z=>travelRow(z)).join('')}</div><div class="button-row"><button class="soft-btn" onclick="addTravelZone()">＋ เพิ่ม Zone</button><button class="primary-btn" onclick="saveTravelZones()">บันทึก Travel Zone</button></div>`)}window.openTravelSettingModal=openTravelSettingModal;
