function saveTravelZones(){const rows=[...travelList.querySelectorAll('.travel-row')].map(r=>({name:r.querySelector('[data-k=name]').value.trim()||'Zone',min:+r.querySelector('[data-k=min]').value||0,max:r.querySelector('[data-k=max]').value===''?null:+r.querySelector('[data-k=max]').value,fee:+r.querySelector('[data-k=fee]').value||0,perKm:+r.querySelector('[data-k=perKm]').value||0})).sort((a,b)=>a.min-b.min);if(!rows.length){toastMsg('ต้องมี Travel Zone อย่างน้อย 1 รายการ');return}settings.travelZones=rows;saveLocal();cloudSaveSettings();closeModal();renderAll();toastMsg('บันทึก Travel Zone แล้ว')}window.saveTravelZones=saveTravelZones;

