async function saveQuotation(){if(!requirePermission('quotation.create'))return;
  const q=calcQuote(), cu=customerById(q.customerId);
  if(!cu){toastMsg('กรุณาเลือกลูกค้า');return}
  if(!q.machineIds.length){toastMsg('กรุณาเพิ่มเครื่องจักรอย่างน้อย 1 เครื่อง');return}
  const old=quotations.find(x=>x.id===quoteEditingId);
  const rec={...q,id:old?.id||quoteNo(),status:old?.status||'ร่าง',createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};
  if(old)quotations=quotations.map(x=>x.id===rec.id?rec:x);else quotations.unshift(rec);
  quoteEditingId=rec.id;quoteEditLabel.textContent=rec.id+' · '+rec.status;
  notifications.unshift({id:uid(),icon:'฿',title:old?'อัปเดตใบเสนอราคา':'สร้างใบเสนอราคา',message:`${rec.id} · ${rec.customer} · ${money(rec.grand)}`,createdAt:new Date().toISOString(),read:false,caseId:rec.caseId||''});
  saveLocal();await cloudUpsertQuotation(rec);renderQuotationList();renderNotifications();toastMsg('บันทึก '+rec.id+' เรียบร้อย')
}
window.saveQuotation=saveQuotation;

