async function syncCloud(silent=false){if(!supa){if(!silent)toastMsg('ยังไม่ได้เชื่อม Cloud');return}try{const [a,b,c,d,e,f,g,h,i,j,k]=await Promise.all([supa.from('service_cases').select('*'),supa.from('technicians').select('*'),supa.from('customers').select('*'),supa.from('machines').select('*'),supa.from('notifications').select('*'),supa.from('system_settings').select('*').eq('id','main').maybeSingle(),supa.from('quotations').select('*'),supa.from('machine_warranties').select('*'),supa.from('machine_documents').select('*'),supa.from('line_customer_requests').select('*'),supa.from('service_reports').select('*')]);if(!a.error&&a.data.length)cases=a.data.map(fromCaseDb);if(!b.error&&b.data.length)technicians=b.data.map(t=>({photo:'',status:'พร้อมรับงาน',skills:'',team:'Technical',...t}));if(!c.error&&c.data.length)customers=c.data.map(fromCustomerDb);if(!d.error&&d.data.length)machines=d.data.map(m=>({photo:'',...m}));if(!e.error&&e.data.length)notifications=e.data.map(n=>({id:n.id,icon:n.icon,title:n.title,message:n.message,createdAt:n.created_at,read:n.is_read,caseId:n.case_id}));if(!f.error&&f.data?.data)settings=mergeSettings(f.data.data);if(!g.error&&g.data.length)quotations=g.data.map(fromQuotationDb);if(!h.error&&h.data.length)warranties=h.data.map(fromWarrantyDb);if(!i.error&&i.data.length)machineDocuments=i.data.map(fromMachineDocumentDb);if(!j.error&&j.data.length)lineRequests=j.data.map(fromLineRequestDb);if(!k.error&&k.data.length)serviceReports=k.data.map(fromServiceReportDb);saveLocal();renderAll();if(!silent)toastMsg('ซิงก์ Cloud แล้ว')}catch(e){if(!silent)toastMsg('ซิงก์ไม่สำเร็จ')}}
