 window.portalIssueMediaChanged=async function(input){window.portalIssuePendingMedia=window.portalIssuePendingMedia||[];for(const file of [...(input.files||[])]){if(window.portalIssuePendingMedia.length>=4){toastMsg('แนบได้สูงสุด 4 ไฟล์');break}if(file.size>3*1024*1024){toastMsg('ไฟล์ '+file.name+' ใหญ่เกิน 3 MB');continue}const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});window.portalIssuePendingMedia.push({name:file.name,type:file.type,size:file.size,data:String(data)})}input.value='';const box=document.getElementById('portalIssueMediaPreview');if(box)box.innerHTML=window.portalIssuePendingMedia.map((f,i)=>`<div class="preview-card">${String(f.type||'').startsWith('video/')?`<video src="${esc(String(f.data))}" controls></video>`:`<img src="${esc(String(f.data))}" alt="upload">`}<small style="display:block;margin-top:6px;color:var(--muted)">${esc(f.name)}</small><button type="button" class="mini-btn" onclick="removePortalIssueMedia(${i})" style="margin-top:6px">ลบ</button></div>`).join('')}
